using System;using System.Drawing;using System.Linq;using System.IO;using System.Windows.Forms;
public class ResponsiveLayoutRegression {
 static void Check(bool yes,string message){if(!yes)throw new Exception(message);}
 [STAThread]public static void Main(){var s=new PaneScope("test",32){Viewport=new Rectangle(10,20,1200,800)};s.Add("a");s.Add("b");s.Root=new PaneSplit{Axis="X",Ratio=.4,First=PaneLayout.Leaf("a"),Second=PaneLayout.Leaf("b")};s.Groups["a"].SelectedTab="one";s.Groups["b"].SelectedTab="two";Func<PaneGroup,Size> min=g=>new Size(300,200);
 Check(PaneLayout.Resolve(s,min),"initial split");var ratio=s.Root.Ratio;var tree=s.Root;
 s.Viewport=new Rectangle(10,20,350,500);Check(!PaneLayout.Resolve(s,min),"preflight remains strict");s.CompactViewport=true;Check(PaneLayout.Resolve(s,min)&&s.CompactGroup=="a","compact fallback");Check(s.Root==tree&&s.Root.Ratio==ratio&&s.Order.SequenceEqual(new[]{"a","b"}),"authored tree retained");Check(s.Groups["a"].ResolvedFrame==new Rectangle(10,52,350,468),"single full view");s.ActiveGroup="b";Check(PaneLayout.Resolve(s,min)&&s.CompactGroup=="b","selection changes compact group");s.Viewport=new Rectangle(10,20,1200,800);Check(PaneLayout.Resolve(s,min)&&s.CompactGroup==null,"automatically restores groups");Check(s.Root.Ratio==ratio&&s.Groups["a"].SelectedTab=="one"&&s.Groups["b"].SelectedTab=="two","selections and ratio retained");s.Viewport=new Rectangle(10,20,120,80);Check(PaneLayout.Resolve(s,min)&&s.CompactGroup=="b","tiny positive viewport retains projection");var dir=Path.Combine(Path.GetTempPath(),"responsive-"+Guid.NewGuid());Directory.CreateDirectory(dir);
 using(var host=new Form()){host.ShowInTaskbar=false;host.StartPosition=FormStartPosition.Manual;host.Bounds=new Rectangle(-20000,-20000,1400,900);host.Show();var p=new PaneCoordinator(host.Handle,Path.Combine(dir,"recover.json"),Path.Combine(dir,"log"),x=>{},32,null,"test",true);
 try{p.SetViewport(new Rectangle(-20000,-20000,1200,800),1);p.AddDocument("preview:one","main",p.Scope.BindingGeneration,p.Scope.StateRevision);p.AddDocument("preview:two","main",p.Scope.BindingGeneration,p.Scope.StateRevision);p.SplitAndMove("preview:two","main","other","right",p.Scope.BindingGeneration,p.Scope.StateRevision);var savedRatio=p.Scope.Root.Ratio;
 p.SetViewport(new Rectangle(-20000,-20000,300,300),2);Check(p.Scope.CompactGroup!=null,"coordinator compacts");p.SelectTab("other","preview:two",p.Scope.BindingGeneration,p.Scope.StateRevision);Check(p.Scope.CompactGroup=="other","select already-selected tab from different compact group");bool rejected=false;try{p.CreateGroup("main","bad","right",p.Scope.BindingGeneration,p.Scope.StateRevision);}catch{rejected=true;}Check(rejected&&!p.Scope.Groups.ContainsKey("bad"),"explicit impossible split still rejects and rolls back");p.SetViewport(new Rectangle(-20000,-20000,1200,800),3);Check(p.Scope.CompactGroup==null&&p.Scope.Groups.Count==2&&p.Scope.Root.Ratio==savedRatio,"coordinator automatically restores authored split");p.SetViewport(new Rectangle(-20000,-20000,80,70),4);Check(p.Scope.CompactGroup!=null,"tiny visible viewport succeeds");}finally{p.Release();}}
 Console.WriteLine("responsive fallback, strict preflight, selection and automatic split restoration verified");}
}
